package apocrypha;

import java.nio.charset.StandardCharsets;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;

/**
 * A response generated by a {@link Route} and sent by the application server.
 *
 * @param status The HTTP status code.
 * @param mimeType The content type.
 * @param data The response body.
 * @param headers Extra response headers, such as {@code Cache-Control}.
 */
public record Response(int status, String mimeType, byte[] data, Map<String, String> headers) {

    /**
     * Create a response. The data array is copied, so the caller may reuse it afterwards.
     * 
     * @param status An HTTP status code.
     * @param mimeType A content type.
     * @param data The body; {@code null} means an empty body.
     * @param headers Extra headers; {@code null} means none.
     */
    public Response {
        Objects.requireNonNull(mimeType, "mimeType");
        data = data == null ? new byte[0] : data.clone();
        headers = headers == null || headers.isEmpty() ? Map.of() : Map.copyOf(headers);
    }

    /**
     * A 200 response with the given content.
     * 
     * @param mimeType A content type.
     * @param data The body.
     * @return A response.
     */
    public static Response ok(String mimeType, byte[] data) {
        return new Response(200, mimeType, data, Map.of());
    }

    /**
     * A 200 response with UTF-8 text content.
     * 
     * @param text The body.
     * @return A response.
     */
    public static Response ok(String text) {
        return new Response(200, "text/plain; charset=utf-8", text.getBytes(StandardCharsets.UTF_8), Map.of());
    }

    /**
     * A 404 response with an empty body.
     * 
     * @return A response.
     */
    public static Response notFound() {
        return new Response(404, "text/plain; charset=utf-8", "Not found".getBytes(StandardCharsets.UTF_8), Map.of());
    }

    /**
     * A response carrying the Cache-Control header.
     * 
     * @param cacheControl A Cache-Control value, such as {@code public, max-age=604800}.
     * @return A copy of this response with the header.
     */
    public Response cache(String cacheControl) {
        Map<String, String> headers = new LinkedHashMap<>(this.headers);
        headers.put("Cache-Control", cacheControl);
        return new Response(status, mimeType, data, headers);
    }

    /**
     * A response carrying an extra header.
     * 
     * @param name A header name.
     * @param value A header value.
     * @return A copy of this response with the header.
     */
    public Response header(String name, String value) {
        Map<String, String> headers = new LinkedHashMap<>(this.headers);
        headers.put(name, value);
        return new Response(status, mimeType, data, headers);
    }

    @Override
    public String toString() {
        return "Response [status=" + status + ", mimeType=" + mimeType + ", bytes=" + data.length + "]";
    }
}
